mapper.select:
	SELECT ubp.perm_scope AS op_type
    FROM sys_business_perm bp
	INNER JOIN sys_user_business_perm ubp ON bp.id = ubp.perm_id
	WHERE ubp.user_id = #{userId, jdbcType=CHAR} AND ubp.org_id = #{orgId, jdbcType=CHAR}
	AND bp.req_url  = #{url,jdbcType=CHAR} AND bp.req_method = #{method,jdbcType=CHAR}

	SELECT ubp.perm_scope AS op_type
    FROM sys_business_perm bp
	INNER JOIN sys_user_business_perm ubp ON bp.id = ubp.perm_id
	WHERE ubp.user_id = #{userId, jdbcType=CHAR} AND ubp.org_id = #{orgId, jdbcType=CHAR}
	AND bp.perm_action = #{action, jdbcType=CHAR}
